SELECT CASE WHEN budget >= 3416000 THEN 'high' WHEN budget >= 1805000 THEN 'mid' ELSE 'low' END budget_bucket, CASE WHEN dept_name IN ('Finance', 'Legal') THEN 'group_a' ELSE 'other' END dept_name_group, COUNT(*) num_departments, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) dept_name_values FROM departments WHERE dept_name NOT IN ('Sales', 'HR', 'Engineering') OR budget IS NULL GROUP BY 1, 2 HAVING num_departments > 3
